                <button class="btn" id="modal-cancel">Cancel</button>
                <button class="btn btn-primary" id="modal-save">Save</button>
            </div>
        </div>
    </div>

    <div class="toast" id="toast">Copied to clipboard!</div>

    <script>
        // Internal State
        let meals = [
            { id: '1', name: 'Garlic Herb Chicken & Rice', cookTime: 25, shelfLife: 4, ingredients: 'Chicken breast, Jasmine rice, Broccoli, Garlic butter' },
            { id: '2', name: 'Smoked Salmon Quinoa Bowl', cookTime: 10, shelfLife: 2, ingredients: 'Smoked salmon, Quinoa, Cucumber, Dill, Lemon' },
            { id: '3', name: 'Lean Beef & Sweet Potato', cookTime: 30, shelfLife: 5, ingredients: '93% Lean ground beef, Sweet potato, Green beans' }
        ];

        // 6 Slots mapping grid deployment
        const slots = [
            { id: 'slot-1', name: 'Mon / Upper Shelf', mealId: null, sequence: 1 },
            { id: 'slot-2', name: 'Tue / Upper Shelf', mealId: null, sequence: 2 },
            { id: 'slot-3', name: 'Wed / Mid Shelf', mealId: null, sequence: 3 },
            { id: 'slot-4', name: 'Thu / Mid Shelf', mealId: null, sequence: 4 },
            { id: 'slot-5', name: 'Fri / Crisper Drawer', mealId: null, sequence: 5 },
            { id: 'slot-6', name: 'Sat / Crisper Drawer', mealId: null, sequence: 6 }
        ];

        let selectedMealId = null;

        // Initialize DOM Elements
        const gridEl = document.getElementById('tetris-grid');
        const poolEl = document.getElementById('meal-pool');
        const totalCookEl = document.getElementById('total-cook');
        const riskScoreEl = document.getElementById('risk-score');
        const modalOverlay = document.getElementById('modal-overlay');
        const toastEl = document.getElementById('toast');

        function init() {
            renderGrid();
            renderPool();
            calculateMetrics();
            lucide.createIcons();
            setupEventListeners();
        }

        function renderGrid() {
            gridEl.innerHTML = '';
            slots.forEach(slot => {
                const matchedMeal = meals.find(m => m.id === slot.mealId);
                let innerContent = `<div class="slot-header">${slot.name}</div>`;

                if (matchedMeal) {
                    const status = getSpoilageStatus(matchedMeal.shelfLife, slot.sequence);
                    innerContent += `
                        <div class="meal-card" style="border-left-color: ${status.color}">
                            <div class="meal-name">${matchedMeal.name}</div>
                            <div class="card-actions">
                                <button class="icon-btn remove-placement" data-slot-id="${slot.id}"><i data-lucide="tritium" style="width:14px;height:14px;">×</i></button>
                            </div>
                        </div>
                    `;
                }

                const slotDiv = document.createElement('div');
                slotDiv.className = `slot ${selectedMealId ? 'active-target' : ''}`;
                slotDiv.dataset.slotId = slot.id;
                slotDiv.innerHTML = innerContent;
                gridEl.appendChild(slotDiv);
            });
            lucide.createIcons();
        }

        function renderPool() {
            poolEl.innerHTML = '';
            meals.forEach(meal => {
                const isAssigned = slots.some(s => s.mealId === meal.id);
                if (isAssigned) return;

                const card = document.createElement('div');
                card.className = `meal-card ${selectedMealId === meal.id ? 'selected' : ''}`;
                card.dataset.mealId = meal.id;

                card.innerHTML = `
                    <div class="meal-card-header">
                        <div class="meal-name">${meal.name}</div>
                    </div>
                    <div class="meal-meta">
                        <span class="tag"><i data-lucide="clock" style="width:12px;height:12px"></i> ${meal.cookTime}m</span>
                        <span class="tag"><i data-lucide="calendar" style="width:12px;height:12px"></i> ${meal.shelfLife}d shelf life</span>
                    </div>
                    <div class="card-actions">
                        <button class="icon-btn edit-meal" data-meal-id="${meal.id}"><i data-lucide="edit-2" style="width:14px;height:14px;"></i></button>
                        <button class="icon-btn delete-meal" data-meal-id="${meal.id}"><i data-lucide="trash-2" style="width:14px;height:14px;"></i></button>
                    </div>
                `;
                poolEl.appendChild(card);
            });
            lucide.createIcons();
        }

        function getSpoilageStatus(shelfLife, daySequence) {
            if (shelfLife < daySequence) {
                return { text: 'High Risk', color: 'var(--danger)' };
            } else if (shelfLife === daySequence) {
                return { text: 'Eat Soon', color: 'var(--warning)' };
            }
            return { text: 'Fresh', color: 'var(--success)' };
        }

        function calculateMetrics() {
            let totalTime = 0;
            let highestRisk = 'Safe';
            let riskColor = 'var(--success)';

            slots.forEach(slot => {
                if (slot.mealId) {
                    const meal = meals.find(m => m.id === slot.mealId);
                    if (meal) {
                        totalTime += meal.cookTime;
                        const status = getSpoilageStatus(meal.shelfLife, slot.sequence);
                        if (status.text === 'High Risk') {
                            highestRisk = 'Spoilage Risk';
                            riskColor = 'var(--danger)';
                        } else if (status.text === 'Eat Soon' && highestRisk !== 'Spoilage Risk') {
                            highestRisk = 'Warning';
                            riskColor = 'var(--warning)';
                        }
                    }
                }
            });

            totalCookEl.innerText = `${totalTime}m`;
            riskScoreEl.innerText = highestRisk;
            riskScoreEl.style.color = riskColor;
        }

        function setupEventListeners() {
            // Card selection mapping
            poolEl.addEventListener('click', (e) => {
                const card = e.target.closest('.meal-card');
                const actionBtn = e.target.closest('.icon-btn');

                if (card && !actionBtn) {
                    const mId = card.dataset.mealId;
                    selectedMealId = (selectedMealId === mId) ? null : mId;
                    renderPool();
                    renderGrid();
                }
            });

            // Handle slot targeted drop/taps
            gridEl.addEventListener('click', (e) => {
                const slotDiv = e.target.closest('.slot');
                const removeBtn = e.target.closest('.remove-placement');

                if (removeBtn) {
                    const sId = removeBtn.dataset.slotId;
                    const slot = slots.find(s => s.id === sId);
                    if (slot) slot.mealId = null;
                    selectedMealId = null;
                    renderGrid();
                    renderPool();
                    calculateMetrics();
                    return;
                }

                if (slotDiv && selectedMealId) {
                    const sId = slotDiv.dataset.slotId;
                    const slot = slots.find(s => s.id === sId);
                    if (slot) {
                        slot.mealId = selectedMealId;
                        selectedMealId = null;
                        renderGrid();
                        renderPool();
                        calculateMetrics();
                    }
                }
            });

            // Create/Edit triggers
            document.getElementById('add-meal-btn').addEventListener('click', () => {
                openModal();
            });

            poolEl.addEventListener('click', (e) => {
                const btn = e.target.closest('.edit-meal');
                const delBtn = e.target.closest('.delete-meal');

                if (btn) {
                    openModal(btn.dataset.mealId);
                }
                if (delBtn) {
                    const id = delBtn.dataset.mealId;
                    meals = meals.filter(m => m.id !== id);
                    renderPool();
                    calculateMetrics();
                }
            });

            // Modal Handlers
            document.getElementById('modal-cancel').addEventListener('click', closeModal);
            document.getElementById('modal-save').addEventListener('click', saveModal);

            // Export Workflow
            document.getElementById('export-btn').addEventListener('click', exportPrepList);
        }

        function openModal(id = null) {
            modalOverlay.classList.add('active');
            if (id) {
                const meal = meals.find(m => m.id === id);
                document.getElementById('modal-title').innerText = 'Edit Meal';
                document.getElementById('edit-id').value = meal.id;
                document.getElementById('edit-name').value = meal.name;
                document.getElementById('edit-cook').value = meal.cookTime;
                document.getElementById('edit-life').value = meal.shelfLife;
                document.getElementById('edit-ingredients').value = meal.ingredients;
            } else {
                document.getElementById('modal-title').innerText = 'Add New Meal';
                document.getElementById('edit-id').value = '';
                document.getElementById('edit-name').value = '';
                document.getElementById('edit-cook').value = '20';
                document.getElementById('edit-life').value = '3';
                document.getElementById('edit-ingredients').value = '';
            }
        }

        function closeModal() {
            modalOverlay.classList.remove('active');
        }

        function saveModal() {
            const id = document.getElementById('edit-id').value;
            const name = document.getElementById('edit-name').value || 'Unnamed Meal';
            const cookTime = parseInt(document.getElementById('edit-cook').value) || 0;
            const shelfLife = parseInt(document.getElementById('edit-life').value) || 1;
            const ingredients = document.getElementById('edit-ingredients').value || '';

            if (id) {
                // Update
                const index = meals.findIndex(m => m.id === id);
                if (index !== -1) {
                    meals[index] = { id, name, cookTime, shelfLife, ingredients };
                }
            } else {
                // Create
                const newId = Date.now().toString();
                meals.push({ id: newId, name, cookTime, shelfLife, ingredients });
            }

            closeModal();
            renderPool();
            renderGrid();
            calculateMetrics();
        }

        function exportPrepList() {
            let output = "=== FRIDGE TETRIS MEAL PREP LIST ===\n\n";

            output += "SCHEDULE:\n";
            slots.forEach(slot => {
                const meal = meals.find(m => m.id === slot.mealId);
                output += `- ${slot.name}: ${meal ? meal.name : 'Empty Slot'}\n`;
            });

            output += "\nGROCERY & INGREDIENT CONSOLIDATION:\n";
            const uniqueIngredients = new Set();
            slots.forEach(slot => {
                if (slot.mealId) {
                    const meal = meals.find(m => m.id === slot.mealId);
                    if (meal && meal.ingredients) {
                        meal.ingredients.split(',').forEach(i => uniqueIngredients.add(i.trim()));
                    }
                }
            });

            if (uniqueIngredients.size > 0) {
                uniqueIngredients.forEach(ing => {
                    if (ing) output += `[ ] ${ing}\n`;
                });
            } else {
                output += "No planned ingredients found.\n";
            }

            // Copy Action
            navigator.clipboard.writeText(output).then(() => {
                toastEl.classList.add('show');
                setTimeout(() => toastEl.classList.remove('show'), 2000);
            });

            // Trigger file fall-back download
            const blob = new Blob([output], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'fridge-tetris-prep-list.txt';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }

        // Run App
        init();
    </script>
</body>
</html>

